-- La Prof
update public.monthly_top_books set summary = 'Dans les couloirs d’un lycée en apparence ordinaire, les silences pèsent plus lourd que les mots. Une enseignante prisonnière d’un mariage aux failles invisibles, une adolescente rejetée par tous depuis un scandale qui continue de la poursuivre, un professeur admiré dont la bienveillance cache peut-être d’autres vérités… Chacun avance avec ses blessures, ses mensonges et ses obsessions, jusqu’au jour où les frontières entre innocence et culpabilité se brouillent. Dans cette mécanique implacable où chaque regard peut condamner et chaque secret devenir une arme, les certitudes s’effondrent une à une, laissant place à une vérité aussi inattendue que vertigineuse.', publisher = '-', page_count = '318', language = 'fr' where month = '2026-09-01' and rank = 1;

-- Les Belles Promesses
update public.monthly_top_books set summary = 'Tout commence par un incendie, un bébé... et un sanglier. Paris est transformé par des travaux titanesques, le cœur d’un homme est écartelé, le monde rural menacé, des femmes sortent de l’oubli, et les membres de la famille Pelletier, toujours plus proches de nous, marchent inexorablement vers leur destin. Au terme d’un effroyable dilemme moral, ce sera l’effondrement ou l’apothéose. Par bonheur, le chat Joseph veille encore. Passionnant, déchirant, enthousiasmant. Un grand roman de Pierre Lemaitre. Les romans de Pierre Lemaitre ont été récompensés par de nombreux prix littéraires nationaux et internationaux. Après l’immense succès du Grand Monde, du Silence et la Colère, et d’Un avenir radieux, il clôt avec Les Belles Promesses sa plongée mouvementée et jubilatoire dans les Trente Glorieuses.', publisher = 'Calmann-Lévy', published_date = '2026-01-06', page_count = '458', language = 'fr' where month = '2026-09-01' and rank = 2;

-- La femme de ménage
update public.monthly_top_books set summary = 'Chaque jour, Millie fait le ménage dans la belle maison des Winchester, une riche famille new-yorkaise. Elle récupère aussi leur fille à l''école et prépare les repas avant d''aller se coucher dans sa chambre, au grenier. Pour la jeune femme, ce nouveau travail est une chance inespérée. L''occasion de repartir de zéro. Mais, sous des dehors respectables, sa patronne se montre de plus en plus instable et toxique. Et puis il y a aussi cette rumeur dérangeante qui court dans le quartier : madame Winchester aurait tenté de noyer sa fille quelques années auparavant. Heureusement, le gentil et séduisant monsieur Winchester est là pour rendre la situation supportable. Mais le danger se tapit parfois sous des apparences trompeuses. Et lorsque Millie découvre que la porte de sa chambre mansardée ne ferme que de l''extérieur, il est peut-être déjà trop tard...', published_date = '2023', language = 'fr' where month = '2026-09-01' and rank = 3;

